{"shader": "float4 render(float2 uv)
{
	float2 texel = 1.0 / uv_size;
	float4 c  = sample_at(uv);
	float4 rt = sample_at(uv + float2(texel.x, 0.0));
	float4 dn = sample_at(uv + float2(0.0, texel.y));
	float edge = saturate((abs(c.a - rt.a) + abs(c.a - dn.a)
	                     + abs(c.r - rt.r) + abs(c.r - dn.r)) * p2);
	float beat = 0.55 + 0.45 * sin(elapsed * 5.0);
	float3 glow = float3(0.1, 1.0, 0.6) * edge * beat * p1;
	return float4(saturate(c.rgb + glow), saturate(c.a + edge * beat * p1));
}
", "p1": 1.0, "p2": 6.0, "p3": 0.0, "p4": 0.0}
